import sys
import datetime
import logging
import inspect
import pprint
from functools import wraps
from moler.util.moler_test import MolerTest  # type: ignore
from taf.ul.sc.perf.exceptions import ProcedureStepError


_base_size = 52
_indent_multiplier = 4


def _log_to_console(msg, log_hierarchy=1, add_timestamp=True, add_new_line=True, add_carriage_return=True):
    """
    Print formatted logs on the console.

    :param msg: str,
    :param log_hierarchy: int, determine how deep should be indent,
    :param add_timestamp: bool.
    :param add_new_line: bool, Add new line sign at te end of msg
    :param add_carriage_return: bool, Add carriage return sign at te begin of msg
    :return: None
    """
    indent = ' ' * _indent_multiplier * log_hierarchy if log_hierarchy else ''
    full_msg = ''
    if add_timestamp:
        msg_time = datetime.datetime.now().strftime('%Y-%m-%d %H:%M:%S')
        full_msg = "[{}]".format(msg_time)
    full_msg = "{}{}{}".format(full_msg, indent, msg)
    full_msg = "\r{}".format(full_msg) if add_carriage_return else full_msg
    full_msg = "{}\n".format(full_msg) if add_new_line else full_msg
    sys.__stdout__.write('{}'.format(full_msg))


def log_debug_function_info(print_args=False):
    def inner_function(fun):
        @wraps(fun)
        def wrapper(*args, **kwargs):
            fun_name = fun.__name__
            logging.debug(msg=_get_start_msg(fun))
            if print_args:
                call_args = inspect.getcallargs(fun, *args, **kwargs)
                logging.debug("{} is running with arguments:\n{}".format(fun_name,
                                                                         pprint.pformat(call_args, indent=1)))
            result = fun(*args, **kwargs)
            returned_value = "***** Returned value: {}".format(pprint.pformat(result, indent=1))
            logging.debug(msg="{}".format(_get_end_msg(fun_name)))
            logging.debug(msg="{}".format(returned_value))

            return result

        return wrapper
    return inner_function


def _get_start_msg(fun):
    return "{} FUNCTION START [{}] from file [{}]".format('*' * 5, fun.__name__, inspect.getsourcefile(fun))


def _get_end_msg(fun_name):
    # TODO add print status of function
    return "{} FUNCTION END [{}].".format('*' * 5, fun_name)


def log_function_info_to_console(msg=None, log_hierarchy=1, banner=False):
    def inner_function(fun):
        @wraps(fun)
        def wrapper(*args, **kwargs):
            log_info_to_console(msg, log_hierarchy, banner)

            result = fun(*args, **kwargs)

            return result

        return wrapper
    return inner_function


def log_info_to_console(msg=None, log_hierarchy=1, banner=False):
    _log_to_console(msg=msg,
                    log_hierarchy=log_hierarchy,
                    add_new_line=True,
                    add_carriage_return=True)
    moler_msg = _generate_banner(msg) if banner else msg
    MolerTest.info(moler_msg)


def log_info_with_status_to_console(msg=None, log_hierarchy=1, status='SKIPPED'):
    size = _base_size - (log_hierarchy - 1) * _indent_multiplier
    align = size - len(msg)
    log_info_to_console(msg="{}{:>{align}}".format(msg, status, align=align), banner=False)


def _generate_banner(msg):
    line_length = '*' * 80
    banner = '\n{}\n*\n*    {}\n*\n{}\n'.format(line_length, msg, line_length)

    return banner


def log_function_status_to_console(msg=None, log_hierarchy=2, ignore_exception=False, add_name_prefix=False):
    # TODO: Add colorful output depend of status
    def inner_function(fun):
        @wraps(fun)
        def wrapper(*args, **kwargs):
            _msg = "[{}] {}".format(args[0].name, msg) if add_name_prefix else msg
            _log_to_console(msg=_msg,
                            log_hierarchy=log_hierarchy,
                            add_new_line=False,
                            add_carriage_return=True)

            result = None
            status = None
            err = None
            try:
                result = fun(*args, **kwargs)
                status = 'OK'
            except Exception as exc:
                status = 'NOT OK'
                err = exc
            finally:
                _print_status(_msg, status, log_hierarchy)
                if status == 'NOT OK':
                    _print_status_details(err, step=_msg, ignore_exception=ignore_exception)
                return result
        return wrapper
    return inner_function


def _print_status(msg, status, log_hierarchy):
    size = _base_size - (log_hierarchy - 1) * _indent_multiplier
    align = size - len(msg)
    _log_to_console(msg="{:>{align}}".format(status, align=align),
                    log_hierarchy=False,
                    add_timestamp=False,
                    add_carriage_return=False,
                    add_new_line=True)


def _print_status_details(err, step, ignore_exception):
    if ignore_exception:
        logging.warning(msg=err)
    else:
        raise ProcedureStepError(err, step)
